  "b1b2-066": {"canDo": "Ma hindan avalike teenuste kvaliteeti ja kättesaadavust ning nimetan probleemi, selle mõjutatud rühma ja praktilise lahenduse.", "goals": {"g_vocab": "Õpilane kasutab teenuste sõnu: avalik teenus, kättesaadavus, kvaliteet, järjekord, e-teenus, taotlus, pöörduma, puudutama, sotsiaaltöötaja, vald.", "g_read": "Õpilane leiab artiklist „Kas teenus jõuab inimeseni?”, Olena kõnest infotelefonile, valla teatest ja Tiiu Raua häälsõnumist probleemi ja mõjutatud rühma.", "g_notice": "Õpilane kasutab ametlikus tekstis umbisikulist tegumoodi (suleti, avaldatakse, on kehtestatud, ei leitud) ja analüüsi lauseid (Probleem puudutab eelkõige…).", "g_use": "Õpilane selgitab sotsiaaltöötajale vajadust, räägib perele 2–3 minutit tulemusest ja kirjutab vallale 150–170-sõnalise hinnangu ja taotluse."}},
  "b1b2-067": {"canDo": "Ma räägin vabatahtlikust tegevusest ja kogukonna algatustest ning selgitan algatuse väärtust konkreetse näitega selle mõjust.", "goals": {"g_vocab": "Õpilane kasutab osalemise sõnu: vabatahtlik, kogukond, algatus, kaasav eelarve, osalema, panustama, vastutama, hääletama, toidupank, talgud.", "g_read": "Õpilane leiab vabatahtlike raadiosaatest, artiklist „Kaasav eelarve: kas iga hääl loeb?” ja kolmest idee kaardist algatuste mõju ja osalemise viisi.", "g_notice": "Õpilane kasutab tegusõna rektsiooni õigesti: osalema milles, panustama millesse, vastutama mille eest, pöörduma kelle poole, toetama keda.", "g_use": "Õpilane valib paarilisega ühe idee, veenab elanike koosolekul 2–3 minutit ja kirjutab naabritele 150–170-sõnalise postituse konkreetse näitega."}},
  "b1b2-068": {"canDo": "Ma väljendan täpselt kohustust, vajadust, luba ja keeldu (peab, tuleb, võib, ei tohi, ei pea) ning valin registri: ametlikus reeglis kasutan vorme „on keelatud”, „on kohustatud”, „rikkumise korral”, „tuleb tagada”.", "goals": {"g_vocab": "Õpilane kasutab reegli sõnu: kodukord, kehtestama, kohustatud, keelatud, lubatud, rikkumine, öörahu, üldkoosolek, jäätmed, sorteerima.", "g_read": "Õpilane eristab Pärna 12 kodukorrast, lünktekstist uue kodu esimesest kuust ja juhatuse ettepanekutest kohustust, luba ja keeldu.", "g_notice": "Õpilane valib igapäevase või ametliku vormi (peab, tuleb, on kohustatud, on keelatud, rikkumise korral) ja kasutab -des-vormi.", "g_use": "Õpilane leiab üldkoosolekul kompromissi, võtab 2–3 minutit sõna ja kirjutab juhatusele 160–180-sõnalise ametliku arvamuse."}},
  "b1b2-069": {"canDo": "Ma esitlen 3 minutiga kohaliku probleemi lahenduse (probleem, vähemalt 2 lahendust, ressursid, riskid, lõplik valik) ja vastan küsimustele.", "goals": {"g_vocab": "Õpilane kasutab ettepaneku sõnu: ettepanek, lahendus, ressurss, risk, kulu, lõplik valik, peatumisala, ülekäigurada, komisjon.", "g_read": "Õpilane leiab kandidaatide debatist, Pääsküla raba näidisettepanekust ja Jüri Männi häälsõnumist probleemi, lahendused, kulud ja riskid.", "g_notice": "Õpilane sõnastab lahenduse tingiva kõneviisiga (See maksaks umbes…; Riskiks oleks…) ja umbisikulise tingivaga (Peatumisala rajataks suvel).", "g_use": "Õpilane esitleb komisjonile 3 minutiga Kase kooli tänava ettepaneku, vastab neljale küsimusele ja kirjutab 140–160-sõnalise ametliku taotluse."}},
  "b1b2-070": {"goals": {"g_read": "Õpilane lahendab ühiskonna teemal Harno B2 vormis kuulamis- ja lugemisülesanded vähemalt 60% igas osas.", "g_notice": "Õpilane kasutab kontrollis kohustuse, loa ja keelu väljendeid ning muudab igapäevase lause ametlikuks.", "g_use": "Õpilane kirjutab sõbrale kirja ja andmete kokkuvõtte, peab kõne ja jõuab paarilisega kompromissini."}},
  "b1b2-071": {"canDo": "Ma eristan fakti, hinnangut ja oletust keeleliste tunnuste järgi (kindlasti, ilmselt, väidetavalt, kahjuks, liiga) ja põhjendan oma valikut tekstist leitud tõendiga.", "goals": {"g_vocab": "Õpilane kasutab info hindamise sõnu: fakt, hinnang, oletus, kuulujutt, allikas, väide, tõend, kontrollima, postitus, jagama.", "g_read": "Õpilane leiab Facebooki arutelust, viiest kuulamislõigust ja Robotlaod OÜ pressiteatest faktid, hinnangud, oletused ja kuulujutud.", "g_notice": "Õpilane tunneb väite kindluse ära sõnade järgi (kindlasti, ilmselt, väidetavalt, kahjuks, liiga) ja kaudse kõneviisi järgi (olevat suletud).", "g_use": "Õpilane küsib müügijuhilt videokõnes tõendeid, annab 2–3 minutiga ülevaate ja kirjutab Liisile 150–170-sõnalise hinnangu pakkumisele."}},
  "b1b2-072": {"canDo": "Ma määran autori seisukoha, tooni ja eesmärgi ning toetan oma järeldust 2–3 tekstikohaga.", "goals": {"g_vocab": "Õpilane kasutab autori hoiaku sõnu: seisukoht, arvamuslugu, hoiak, toon, eesmärk, sõnavalik, rõhutama, kritiseerima, veenma, vihje.", "g_read": "Õpilane määrab Lepiku arvamusloost „Koolisöök ei ole muuseum”, Kaia Mägi raadiointervjuust ja Helgi kõnest seisukoha, tooni ja eesmärgi.", "g_notice": "Õpilane annab autori seisukoha edasi (Autor leiab, et…; Autori sõnul…; olevat) ja tõestab seda tekstikohaga.", "g_use": "Õpilane tutvustab raadiokõnes 2–3 minutiga Lepiku lugu, arutleb teise helistajaga ja kirjutab loo alla 150–170-sõnalise kommentaari."}},
  "b1b2-073": {"canDo": "Ma hindan argumendi tugevust (väide, põhjus, näide, tõend, vastuväide), selgitan, miks argument on nõrk, ja pakun, kuidas seda tugevdada.", "goals": {"g_vocab": "Õpilane kasutab argumendi sõnu: argument, põhjendus, näide, vastuväide, üldistus, pealkiri, koondamine, tugev, nõrk.", "g_read": "Õpilane hindab köökide koondamise uudisest, probleemartiklist „Ühisköök või oma köök” ja argumendikaartidelt argumentide tõendeid ja nõrkusi.", "g_notice": "Õpilane avab pealkirja -mine-nimisõna (köökide koondamine = köögid koondatakse) ja tugevdab nõrga argumendi põhjuse, tõendi või näitega.", "g_use": "Õpilane kaitseb arutelus üht lahendust andmetega, võtab kuni 3 minutit sõna ja kirjutab linnavolikogule 160–180-sõnalise arvamuse."}},
  "b1b2-074": {"canDo": "Ma teen tekstist kokkuvõtte, mis ei moonuta sisu ega numbreid, ja lisan eraldi oma reaktsiooni nii, et autori sisu ja minu hinnang on selgelt lahus.", "goals": {"g_vocab": "Õpilane kasutab kokkuvõtte sõnu: kokkuvõte, reaktsioon, käsitlema, järeldus, moonutama, analüüs, võimalus, parandus, faktikontroll, selguma.", "g_read": "Õpilane leiab koolitoidu analüüsi kokkuvõttest, faktikontrolli juhendist, Mareti loengust ja Kase kooli toimikust põhimõtted ja eksitavad väited.", "g_notice": "Õpilane alustab kokkuvõtet õigesti (Analüüsis käsitletakse…), ei moonuta modaalsust ega arve ja eraldab reaktsiooni (Minu arvates…).", "g_use": "Õpilane esitleb lapsevanematele 3 minutiga faktikontrolli, vastab küsimustele ja kirjutab toimetusele 160–180-sõnalise parandussoovi."}},
  "b1b2-075": {"goals": {"g_read": "Õpilane lahendab meedia teemal Harno B2 vormis kuulamis- ja lugemisülesanded vähemalt 60% igas osas ja teeb järeldusi.", "g_notice": "Õpilane eristab kontrollis fakti ja hinnangut, kasutab õigeid vorme ja kaudset kõneviisi.", "g_use": "Õpilane kirjutab toimetusele 140-sõnalise kirja ja 180-sõnalise arutluse ning jõuab paarilisega ühisele otsusele."}},
